const WEIGHTS = { communication_skills: 20, professional_attitude: 18, english_fluency: 15, confidence_level: 12, relevant_experience_role_fit: 20, problem_solving: 10, computer_skills: 5 };
// Recalibrated. At 0.5, a candidate rated Intermediate on everything scored 50%
// automatically, and the jump from bad=0 to 0.5 was the whole gap - there was no
// band for "showed something, weakly". At 0.7, Good across the board lands exactly
// on the Hire threshold (70), so advancing takes real quality rather than comfort.
const RATING_FRACTION = { excellent: 1.0, good: 0.7, intermediate: 0.4, bad: 0.0 };
const T_ADVANCE = 70;
const T_CONSIDER = 49;
const PRIOR_KEYS = { communication_skills: 'communicationSkills', english_fluency: 'englishFluency', confidence_level: 'confidenceLevel' };
const CORE_DIMS = ['communication_skills', 'professional_attitude'];
// 60 let an interview covering barely half the role pass as scorable. Raised so a
// thin interview is reported as insufficient evidence rather than as a low score,
// which is a different message to a hiring manager.
const MIN_ASSESSED_WEIGHT = 75;
const LEVELS = ['bad', 'intermediate', 'good', 'excellent'];
function norm(s) { return String(s == null ? '' : s).trim().toLowerCase(); }
function titleCase(s) { const x = norm(s); return x ? x.charAt(0).toUpperCase() + x.slice(1) : x; }
function isNotAssessed(r) { const x = norm(r); return x === '' || x === 'not assessed' || x === 'notassessed' || x === 'n/a' || x === 'na' || x === 'none'; }
function levelIdx(r) { return LEVELS.indexOf(norm(r)); }
function hasEvidence(v) { if (Array.isArray(v)) return v.some((x) => String(x || '').trim()); return String(v == null ? '' : v).trim().length > 0; }
function toArray(v) { if (Array.isArray(v)) return v.filter((x) => String(x || '').trim()); const s = String(v == null ? '' : v).trim(); return s ? [s] : []; }
/* Bands widened 2026-09-10, measured not guessed. Across 16 real interviews the
   prior model emitted communicationSkills of only 5 or 6, and confidenceLevel of
   only 4-6. Under >=6 Good / >=4 Intermediate that collapsed to TWO possible
   ratings for 32 of the 100 points: median 41, and NINE of sixteen interviews
   piled into 40-43. Widening to >=5 Good / >=3 Intermediate moves the median to 55
   and leaves one interview in that band.
   This fixes what a score MEANS, not how well it separates people. Simulated on
   the same 16: distinct scores stayed 9/16 either way, and Hire stayed zero. The
   raters themselves use two labels - professional_attitude was Good for 14 of 16
   and relevant_experience_role_fit Intermediate for 14 of 16 - and no arithmetic
   here can undo that. */
function priorToRating(n) { n = Number(n); if (!Number.isFinite(n)) return null; if (n >= 8) return 'Excellent'; if (n >= 5) return 'Good'; if (n >= 3) return 'Intermediate'; if (n >= 1) return 'Bad'; return null; }
function getAssessment(item) { const j = item.json || {}; if (j.output && typeof j.output === 'object') return j.output; if (j.competencies && typeof j.competencies === 'object') return j; const raw = j.text || j.response || j.data || ''; const m = String(raw).match(/\{[\s\S]*\}/); if (m) { try { return JSON.parse(m[0]); } catch (e) {} } return {}; }
function getPriors(item) { try { const b = $('Webhook').first().json.body || {}; if (b.evaluation) return b.evaluation; } catch (e) {} return (item.json && item.json.body && item.json.body.evaluation) || item.json.__priors || {}; }
/* How the voice session ended, as reported by the backend - it is the only party
   that knows, because it is the party that calls ws.close(). Shape:
   { cause, completedByServer, closeCode, phaseReached, earlyEnd }. Absent on any
   older payload, in which case every field reads undefined and nothing changes. */
function getSessionEnd(item) { try { const b = $('Webhook').first().json.body || {}; if (b.sessionEnd && typeof b.sessionEnd === 'object') return b.sessionEnd; } catch (e) {} const j = (item.json && item.json.body) || {}; return (j.sessionEnd && typeof j.sessionEnd === 'object') ? j.sessionEnd : {}; }
function enforcePrior(key, node, priorVal) { const priorRating = priorToRating(priorVal); if (key === 'english_fluency' && priorRating === null) { return { rating: 'Not Assessed', note: 'english_not_tested' }; } if (priorRating === null) return { rating: node.rating, note: 'no_prior' }; if (node.assessed === false) { return { rating: priorRating, note: 'reverted_llm_notassessed' }; } let r = node.rating; if (isNotAssessed(r) || levelIdx(r) < 0) { return { rating: priorRating, note: 'reverted_invalid_or_na' }; } const li = levelIdx(r), pi = levelIdx(priorRating); if (li === pi) return { rating: priorRating, note: 'matches_prior' }; const justified = node.adjusted_from_prior === true && hasEvidence(node.evidence); /* The prior is a fast gpt-4o-mini read; this assessor weighs evidence. Capping it to one band meant the careful judgement was governed by the quick one - the main reason thin interviews kept mid scores. An evidence-backed DOWNWARD move is now accepted at any distance; upward moves still stay within one band so the assessor cannot inflate. */ if (justified && li < pi) { return { rating: titleCase(r), note: 'override_accepted_down' }; } if (Math.abs(li - pi) === 1 && justified) { return { rating: titleCase(r), note: 'override_accepted' }; } return { rating: priorRating, note: 'override_rejected' }; }
const out = [];
for (const item of $input.all()) {
  const a = getAssessment(item);
  const comp = a.competencies || {};
  const priors = getPriors(item);
  let earned = 0;
  let assessedMax = 0;
  const ratings = {};
  const evidence = {};
  const notAssessed = [];
  const overrides = {};
  let coreMissing = false;
  for (const [key, max] of Object.entries(WEIGHTS)) {
    const node = comp[key] || {};
    let rating = node.rating;
    if (PRIOR_KEYS[key]) { const res = enforcePrior(key, node, priors[PRIOR_KEYS[key]]); rating = res.rating; overrides[key] = res.note; } else if (node.assessed === false) { rating = 'Not Assessed'; }
    evidence[key] = toArray(node.evidence);
    if (isNotAssessed(rating) || !(norm(rating) in RATING_FRACTION)) { ratings[key] = 'Not Assessed'; notAssessed.push(key); if (CORE_DIMS.includes(key)) coreMissing = true; continue; }
    earned += RATING_FRACTION[norm(rating)] * max;
    assessedMax += max;
    ratings[key] = titleCase(rating);
  }
  let status = 'scored';
  // Score out of the FULL role weight, not just what happened to be covered.
  // Dividing by assessedMax silently deleted every uncovered dimension from the
  // denominator, so a one-minute interview that touched 3 of 7 dimensions was
  // marked out of 80 and read 66%. Stage 3 deducts for what a candidate did not
  // evidence; Stage 2 now does the same, and `coverage` keeps the reason visible.
  const TOTAL_WEIGHT = Object.values(WEIGHTS).reduce((a, b) => a + b, 0);
  let score = Math.round((earned / TOTAL_WEIGHT) * 100);
  const coverage = Math.round((assessedMax / TOTAL_WEIGHT) * 100);
  let recommendation;
  if (coreMissing || assessedMax < MIN_ASSESSED_WEIGHT) { status = 'insufficient_data'; recommendation = 'Consider'; } else { recommendation = score >= T_ADVANCE ? 'Hire' : score >= T_CONSIDER ? 'Consider' : 'Reject'; }
  /* An interview the candidate closed before the English phase cannot produce a
     comparable number. Upstream, `phase < 3` zeroes the English prior outright,
     so 15 of the 100 points are forfeited by construction rather than by any
     judgement of the candidate; the realistic ceiling for such a run is about 60
     and Hire is unreachable. Emitting "41 / Reject" invites a hiring manager to
     compare that against someone who finished. `sessionEnd.earlyEnd` is decided
     by the backend because only it knows which side closed the socket. */
  const endedEarly = getSessionEnd(item).earlyEnd === true;
  if (endedEarly && status === 'scored') { status = 'insufficient_data'; recommendation = 'Consider'; }
  let finalHr = String(a.overall_job_fit_narrative || '').trim();
  let summary = String(a.summary || '').trim();
  if (status === 'insufficient_data') { /* Emit NO number. A percentage invites a
    hiring manager to compare candidates who were never actually measured; the UI
    already renders a null score as an em dash with neutral colouring, so the honest
    output is the dash plus the coverage figure and the note below. */ score = null;
    const note = endedEarly ? 'NOTE: The candidate left the interview before it finished, so later parts of it were never reached and no reliable score can be given. Recommend inviting them to complete the interview before deciding.' : 'NOTE: Insufficient interview evidence for a reliable score. Recommend a re-interview before deciding.'; finalHr = finalHr ? (finalHr + '\n\n' + note) : note; summary = summary ? (summary + '\n\n' + note) : note; }
  out.push({ json: { output: { 'Summary': summary, 'Strengths': toArray(a.strengths), 'Weaknesses': toArray(a.weaknesses), 'Final HR Evaluation': finalHr, 'Recommendation': recommendation, 'Overall-score': score, 'Communication Skills': ratings.communication_skills || 'Not Assessed', 'English Fluency': ratings.english_fluency || 'Not Assessed', 'Confidence Level': ratings.confidence_level || 'Not Assessed', 'Problem Solving': ratings.problem_solving || 'Not Assessed', 'Computer Skills': ratings.computer_skills || 'Not Assessed', 'Professional Attitude': String(a.professional_attitude_narrative || '').trim(), 'status': status, 'not_assessed': notAssessed, 'coverage': coverage, 'ended_early': endedEarly } } });
}
return out;
